'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Save, ClipboardCheck } from 'lucide-react';

export default function MarksEntryPage() {
    const [subjects, setSubjects] = useState<any[]>([]);
    const [selectedSubject, setSelectedSubject] = useState('');
    const [students] = useState([
        { id: 'student-a-001', name: 'Alpha Student', roll: 'CS001' },
    ]);
    const [marks, setMarks] = useState<Record<string, number>>({});
    const [saved, setSaved] = useState(false);

    useEffect(() => {
        const load = async () => {
            try {
                const res = await api.get<any[]>('/api/admin/subjects');
                if (res.success) setSubjects(res.data);
            } catch (e) { }
        };
        load();
    }, []);

    const handleSubmit = async () => {
        try {
            const entries = Object.entries(marks).map(([student_id, m]) => ({
                student_id, marks: m, max_marks: 100,
            }));
            await api.post('/api/faculty/marks/submit', {
                subject_id: selectedSubject,
                entries,
            });
            setSaved(true);
            setTimeout(() => setSaved(false), 3000);
        } catch (e) { }
    };

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                Internal Marks Entry
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>Enter and submit marks for approval</p>

            <div className="card" style={{ padding: 28 }}>
                <div className="form-group" style={{ maxWidth: 400, marginBottom: 24 }}>
                    <label>Subject</label>
                    <select value={selectedSubject} onChange={(e) => setSelectedSubject(e.target.value)}>
                        <option value="">Select subject</option>
                        {subjects.map(s => <option key={s.id} value={s.id}>{s.name} ({s.code})</option>)}
                    </select>
                </div>

                <div className="table-container" style={{ marginBottom: 20 }}>
                    <table>
                        <thead>
                            <tr>
                                <th>Roll No</th>
                                <th>Name</th>
                                <th>Marks</th>
                                <th>Max Marks</th>
                            </tr>
                        </thead>
                        <tbody>
                            {students.map(s => (
                                <tr key={s.id}>
                                    <td>{s.roll}</td>
                                    <td style={{ fontWeight: 600 }}>{s.name}</td>
                                    <td>
                                        <input type="number" min="0" max="100" value={marks[s.id] || ''}
                                            onChange={(e) => setMarks({ ...marks, [s.id]: parseFloat(e.target.value) })}
                                            style={{ width: 80, padding: '6px 10px', borderRadius: 6, border: '1px solid #e2e6ea', fontSize: 14 }}
                                        />
                                    </td>
                                    <td>100</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                    <button className="btn-primary" onClick={handleSubmit} disabled={!selectedSubject}>
                        <ClipboardCheck size={16} /> Submit for Approval
                    </button>
                    {saved && <span style={{ color: '#059669', fontSize: 14, fontWeight: 600 }}>✓ Marks submitted!</span>}
                </div>
            </div>
        </div>
    );
}
